/// `Double.compare` (also `Comparator.comparingDouble`, `Collections.sort` / `Arrays.sort` of doubles): every NaN is
/// equal to itself and above +Infinity, -0.0 < 0.0. Unlike `f64::total_cmp`, which puts a NaN with its sign bit set
/// (what 0.0 / 0.0 gives on x86-64) below -Infinity.
#[inline]
pub fn java_cmp(a: f64, b: f64) -> std::cmp::Ordering {
    match (a.is_nan(), b.is_nan()) {
        (true, true) => std::cmp::Ordering::Equal,
        (true, false) => std::cmp::Ordering::Greater,
        (false, true) => std::cmp::Ordering::Less,
        _ => a.total_cmp(&b),
    }
}

#[cfg(test)]
mod java_cmp_tests {
    #[test]
    fn nan_sorts_last_as_in_java() {
        let z = std::hint::black_box(0.0f64);
        let nan = z / z; // computed at run time: on x86-64 the NaN with the sign bit set
        let mut v = vec![0.5, nan, -1.0, f64::INFINITY, 0.0, -0.0, f64::NAN, f64::NEG_INFINITY];
        let mut t = v.clone();
        t.sort_by(|a, b| a.total_cmp(b));
        v.sort_by(|a, b| super::java_cmp(*a, *b));
        // Double.compare: -Inf, -1, -0.0, 0.0, 0.5, Inf, then the NaNs
        let head: Vec<u64> = v[..6].iter().map(|x| x.to_bits()).collect();
        let want: Vec<u64> = [f64::NEG_INFINITY, -1.0, -0.0, 0.0, 0.5, f64::INFINITY].iter().map(|x| x.to_bits()).collect();
        assert_eq!(head, want);
        assert!(v[6].is_nan() && v[7].is_nan());
        // what total_cmp did instead (finding 34): the run-time NaN first
        assert!(!nan.is_sign_negative() || t[0].is_nan());
    }
}
